function R({registerIndicator:w,sourceValues:S,nulls:h}){w({id:"oa-agc",name:"Ehlers Automatic Gain Control (AGC)",category:"Filters",placement:"pane",inputs:[{key:"decay",type:"number",label:"Decay",default:.991,min:.9,max:.9999,step:.001,tooltip:"Peak decay factor per bar (0.991 is roughly a 110-bar half-life)."},{key:"hpLength",type:"number",label:"HP Length",default:48,min:1,max:5e3,step:1,tooltip:"Highpass cutoff period: removes trend cycles longer than this."},{key:"ssLength",type:"number",label:"SS Length",default:10,min:1,max:5e3,step:1,tooltip:"Super Smoother cutoff: removes noise cycles shorter than this."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"agc",type:"line",title:"AGC",style:{color:"#2962ff",lineWidth:2}},{key:"filter",type:"line",title:"Filter",style:{color:"#9598a1",lineWidth:1}}],levels:()=>[{price:1,title:"+1",color:"#9598a1",dashed:!0},{price:0,title:"Zero",color:"#9598a1",dashed:!0},{price:-1,title:"-1",color:"#9598a1",dashed:!0}],calc(p,n){const v=Math.min(.9999,Math.max(.9,Number(n.decay)||.991)),P=Math.max(1,Math.floor(Number(n.hpLength)||48)),E=Math.max(1,Math.floor(Number(n.ssLength)||10)),r=S(p,n.source??"close"),a=p.length,u=Math.sqrt(2)*Math.PI,f=u/P,l=Math.exp(-f),m=2*l*Math.cos(f),y=-l*l,G=(1+m-y)/4,d=u/E,i=Math.exp(-d),N=2*i*Math.cos(d),b=-i*i,H=1-N-b,t=new Array(a).fill(0),o=new Array(a).fill(0),g=new Array(a).fill(NaN),M=new Array(a).fill(NaN);let s=1e-7;for(let e=0;e<a;e++){const x=r[e],c=e>=1?r[e-1]:NaN,A=e>=2?r[e-2]:NaN,C=Number.isFinite(x)?x:Number.isFinite(c)?c:0,k=Number.isFinite(c)?c:C,I=Number.isFinite(A)?A:k,W=e>=1?t[e-1]:0,q=e>=2?t[e-2]:0;t[e]=G*(C-2*k+I)+m*W+y*q;const D=e>=1?o[e-1]:t[e],Q=e>=2?o[e-2]:e>=1?t[e-1]:t[e];o[e]=H*t[e]+N*D+b*Q;const F=Number.isFinite(o[e])?o[e]:0;s=v*s;const L=Math.abs(F);L>s&&(s=L),g[e]=Number.isFinite(o[e])?o[e]:NaN,M[e]=s>0?F/s:0}return{agc:h(M),filter:h(g)}}})}export{R as default};
